{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Tropisetron, an N-methyl tropane ester with an aromatic carboxylate, reached a brain/plasma ratio of 2.5 in mice and was classified as high permeability; the query shares the same N-methyl tropane ester core, directly supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "[18F]MCL-322, an N-methyl tropane ester with an aryl substituent, showed fast brain entry and high striatal uptake (3.23 %ID/g) in rat PET, indicating efficient BBB passage; the query is closely analogous in structure and ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A fluoroethyl-substituted nortropane acetate displayed high, rapid striatal uptake in rat PET, supporting BBB permeability for N-alkyl tropane esters like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "N-methylpiperidin-4-yl 4-iodobenzoate entered the rat brain after intravenous injection and labeled BChE-rich regions, demonstrating that N-methyl azacyclic aryl esters penetrate the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "An N-methyl bridged bicyclic amine with an aromatic heterocycle rapidly entered the human brain in PET studies, reinforcing that the query's N-methyl bicyclic amine and aromatic ester features are compatible with robust CNS penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an N-methyl tropane aryl ester. Multiple close analogues with very high assay-transfer scores demonstrate rapid and efficient brain uptake in rodents, monkeys, and humans, so meaningful CNS access is expected.",
  "evidence_gaps": [
    "No direct experimental measurement exists for the exact query molecule; the prediction relies on close structural analogues.",
    "Efflux-transporter status was not explicitly measured for the query, but consistent in vivo brain uptake across analogous N-methyl tropane esters mitigates this concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

